import{_ as l,O as t,H as r,f as i,i as c,k as a,b as s}from"./chunks/framework.Ch3ZxHbh.js";const k=JSON.parse('{"title":"Football is back! But what about the fans?","description":"","frontmatter":{},"headers":[],"relativePath":"blog/football.md","filePath":"blog/football.md"}'),d={name:"blog/football.md"};function h(u,e,p,b,m,f){const n=t("SeriesChart"),o=t("YoYChart");return r(),i("div",null,[e[0]||(e[0]=c('<h1 id="football-is-back-but-what-about-the-fans" tabindex="-1">Football is back! But what about the fans? <a class="header-anchor" href="#football-is-back-but-what-about-the-fans" aria-label="Permalink to &quot;Football is back! But what about the fans?&quot;">​</a></h1><div class="byline"><span class="byline-author">Alexander Götz</span><span class="byline-date">18 September 2020</span></div><p>This weekend marks the start of the new football season in Switzerland and Germany. Because of the Corona crisis, the Swiss Football League adjusted its schedule for 2020/21. Beyond postponements, fans face new rules they will have to adapt to. But are they ready, and have they already bought their tickets?</p><p>The Swiss Football Association had been working on a <a href="https://www.football.ch/portaldata/27/resources/dokumente/diverses/Covid_Schutzkonzept_August2020_DE.pdf" target="_blank" rel="noreferrer">protection concept</a> for handling fans in a Corona-compliant way. Alongside individual rules, clubs had to follow guidelines such as a cap of 1000 people in the stadium until the end of October. From October, the Federal Council allowed more than 1000 people at major events in principle, but protecting citizens, and stadium-goers, fell to the cantons, so fans had to adapt to regional conditions.</p><p>Using our cultural-events indicator, we see a level shift since the start of the year that is unique in the last four years, illustrating uncertainty about attending events in general. The chart below shows the search terms <em>spielplan</em> (match schedule) and <em>saisonkarte</em> (season ticket) alongside <em>maskenpflicht</em> (mask requirement) and <em>fallzahlen</em> (case numbers). Interest in match schedules and season tickets dropped to unprecedented lows, while case numbers reached a new record, far above the first wave.</p>',5)),a(n,{src:"https://cdn.jsdelivr.net/gh/trendecon/media-content@master/data_examples/article_6.csv",ids:["saisonkarte","spielplan","maskenpflicht","fallzahlen"],from:"2020-01-01",eventset:"reopening",title:"Football and the pandemic",subtitle:"2020; dashed lines mark Swiss reopening phases"}),e[1]||(e[1]=s("p",null,"The cultural-events index makes the uncertainty about attending events clear. A year-on-year comparison shows 2020 sitting well below earlier years.",-1)),a(o,{series:"ch/social",years:[2017,2018,2019,2020],until:"09-17",title:"Cultural events index: year-on-year"}),e[2]||(e[2]=s("p",null,"Given uncertainty about a second wave and possible new restrictions, we expected stadium attendance to stay low. That same uncertainty affected most people, with possible knock-on effects not just on ticket sales but on consumer spending more broadly.",-1))])}const _=l(d,[["render",h]]);export{k as __pageData,_ as default};
